This worker pool deadlocks about one run in fifty under load. Find the race and fix it:

func (p *Pool) Submit(job Job) {
    p.mu.Lock()
    if p.closed { p.mu.Unlock(); return }
    p.pending++
    p.mu.Unlock()
    p.queue <- job
}

func (p *Pool) Close() {
    p.mu.Lock()
    p.closed = true
    for p.pending > 0 { p.cond.Wait() }
    close(p.queue)
    p.mu.Unlock()
}
